body.script:
//
					const cfg      = document.getElementById('cfg').dataset;
					const ASSET    = cfg.asset;
					const REFRESH  = parseInt(cfg.refresh, 10) * 1000;
					// Epoch ms of the next scheduled gamma-line auto-refresh —
					// drives the #refresh-countdown toolbar label. Re-armed for
					// real by scheduleGammaRefresh() / refreshFourLegGamma()'s
					// finally.
					let nextRefreshAt = Date.now() + REFRESH;
					// "Timeframe" dropdown — same options as the Delta/Gamma/
					// Strike Gamma charts' own dropdown; was 15m by default,
					// then changed to 4h (matching those pages), then to 1d
					// per a further product decision (2026-08-19), then back
					// to 4h per a still later product decision, then to 1h
					// per a further product decision (2026-09-01), then back
					// to 4h per a further product decision (2026-09-05) — see
					// TF_WINDOW below for the per-timeframe visible-window
					// convention this page shares with those pages.
					let INTERVAL = '1h';
					// Coinbase spot, same symbol convention /tm/<asset> uses
					// (server-side _COINBASE_SYMBOL_MAP).
					const COINBASE_SYMBOL = { BTC: 'BTC-USD', ETH: 'ETH-USD' }[ASSET] || (ASSET + '-USD');
					document.getElementById('exchange-label').textContent = 'Coinbase · ' + COINBASE_SYMBOL;
					const klineUrl = (iv, limit) => '/api/klines-coinbase/' + ASSET + '?interval=' + iv + '&limit=' + limit;
					// "Expiry" dropdown — which expiry's trades feed the 4
					// gamma legs. Used to offer a fixed Nearest/Weekly/
					// Monthly option set (each resolved server-side via
					// four_leg_gamma_json's own ?expiry= mode strings) —
					// replaced per product decision with a dynamically
					// loaded list of every actually-active (non-expired)
					// instrument for ASSET (see loadExpiries() below,
					// sourced from /api/expiries/<asset>), so any real
					// expiry can be picked directly rather than only
					// through the weekly_expiry/monthly_expiry settings
					// indirection or the nearest/nearest_plus_1/
					// nearest_plus_2 ordinal family. Every option now
					// ISOLATES trades to that one instrument's own trades
					// via four_leg_gamma_json's own ?instrument= override —
					// there is no cumulative "all expiries at once" option
					// on this dropdown (never was). SELECTED_INSTRUMENT holds
					// the currently chosen instrument string.
					let SELECTED_INSTRUMENT = null;
					// "Window" dropdown — trailing-hours trade window fed
					// into that same expiry's trades, independent of
					// SELECTED_INSTRUMENT. Current set: 1h/4h/8h/24h/48h/72h
					// plus "All" (?hours=all — skips the
					// trailing-hours trade filter entirely; a number in every
					// other case), 24h default (moved 24h → 4h per product
					// decision (2026-09-07), when 12h/16h were added, then back
					// 4h → 24h per a further product decision (2026-09-23)). This set and its default
					// have moved many times across product decisions (see
					// main.py's own FOUR_LEG_WINDOW_HOURS_CHOICES comment for
					// the history); a "00:00 UTC" (?hours=midnight) and an
					// "Auto (Time to Expiry)" (?hours=auto) option were both
					// offered here at various points — the server-side
					// resolutions for both are unchanged and still reachable
					// by a direct API call, just no longer in this dropdown.
					let WINDOW_HOURS = 24;
					// If ?hours=auto is ever driven in (not from this
					// dropdown any more — see above), this holds the numeric
					// hours the server resolved it to (its `window_hours`
					// response field, via _auto_window_hours()); null
					// otherwise, so windowLabel() falls back to a plain label.
					let autoResolvedHours = null;
					// Each Expiry option ISOLATES trades to that one instrument
					// (four_leg_gamma_json's own `?instrument=`). The route still
					// supports a `?cumulative=1` mode (span every instrument
					// expiring between "now" and the selected one) reachable by a
					// direct API call, but this page no longer offers a checkbox
					// for it — removed per product decision, along with /tm's.
					const fourLegGammaUrl = () =>
						'/api/four-leg-gamma/' + ASSET + '?instrument=' + SELECTED_INSTRUMENT + '&hours=' + WINDOW_HOURS;


					// Same "Last trade:" footer field the Delta Chart uses —
					// a growing gap between this and "now" is the at-a-glance
					// signal that dankbit_ws has stalled (its DB connection
					// can die without crashing the container, silently
					// dropping every trade — see dankbit_ws_batch.py).
					const LAST_TRADE_URL = '/api/last-trade/' + ASSET;
					let   lastTradeTs = null;
					// Trade count for the currently selected Window/Expiry —
					// same `trade_count` field /api/four-leg-gamma already
					// returns (len(trades) over the resolved instrument's
					// domain), just not previously surfaced on this page.
					// null until the first refreshFourLegGamma() resolves.
					let   tradeCount = null;

					// Shown in real UTC (not a browser-local shift) — this is a
					// staleness check against server time, not a chart position.
					function formatLastTradeTs(iso) {
						if (!iso) return null;
						return new Date(iso).toLocaleString('de-DE', {
							timeZone: 'UTC',
							year: 'numeric', month: '2-digit', day: '2-digit',
							hour: '2-digit', minute: '2-digit', second: '2-digit',
						}) + ' UTC';
					}

					// Same browser-local-timezone shift every other TV chart page
					// in this addon applies — Lightweight Charts always renders
					// epoch seconds as UTC wall-clock time, so every timestamp fed
					// into the chart is pre-shifted by the viewer's own current
					// UTC offset first.
					const tzOffset = (() => {
						let zone;
						try {
							zone = Intl.DateTimeFormat().resolvedOptions().timeZone;
						} catch (e) {
							return 0;
						}
						const d = new Date();
						const utc = new Date(d.toLocaleString('en-US', { timeZone: 'UTC' }));
						const local = new Date(d.toLocaleString('en-US', { timeZone: zone }));
						return (local - utc) / 1000;
					})();

					const THEME_STORAGE_KEY = 'dankbit_theme';
					let DARK_MODE = localStorage.getItem(THEME_STORAGE_KEY) === 'dark';
					function rulerColor() { return DARK_MODE ? '#aaaaaa' : '#555555'; }

					// "Settings" button/dialog (see openSettingsModal() below,
					// after Ruler) — user-pickable colors for this page's own
					// 4 gamma-leg lines plus the Dominant Leg, Δ0 and γ flip lines,
					// persisted per-browser to localStorage under a key
					// completely separate from the Delta Chart's own
					// 'dankbit_chart_colors' (dankbit_templates.xml) — the
					// two pages' color settings are deliberately independent,
					// not shared/synced, since they're maintained by different
					// people (Delta Chart: Thales's dev; this page: dankbit's
					// own). No line-style picker (unlike the Delta Chart's own
					// modal) since these lines are always solid/dotted
					// createPriceLine()s, never user-restylable. Defaults match this page's original
					// fixed colors (LC/LP black, SC/SP orange) — no longer
					// tied to DARK_MODE the way the old axisBlack()-based LC/LP
					// color was, same as every other user-configurable color
					// elsewhere in this addon (e.g. the Delta Chart's own Bands/
					// Smart Liquidity colors, which are likewise fixed once
					// chosen rather than swapping with the theme).
					const COLOR_STORAGE_KEY = 'dankbit_4l_chart_colors';
					const DEFAULT_COLORS = {
						bcg: '#000000', bpg: '#000000', scg: '#fb8c00', spg: '#fb8c00', dominant: '#8e24aa',
						deltazero: '#2e7d32', gammaflip: '#7e57c2', maxpain: '#00acc1',
					};
					let chartColors = Object.assign({}, DEFAULT_COLORS);
					try {
						const savedColors = JSON.parse(localStorage.getItem(COLOR_STORAGE_KEY) || '{}');
						Object.keys(DEFAULT_COLORS).forEach(key => {
							if (savedColors[key]) chartColors[key] = savedColors[key];
						});
					} catch (e) { /* malformed stored value — fall back to defaults */ }

					document.getElementById('theme-select').value = DARK_MODE ? 'dark' : 'light';
					document.body.classList.toggle('dark', DARK_MODE);

					const chart = LightweightCharts.createChart(document.getElementById('chart-container'), {
						width: window.innerWidth, height: window.innerHeight,
						layout: {
							background: { type: 'solid', color: DARK_MODE ? '#000000' : '#ffffff' },
							textColor: DARK_MODE ? '#d1d4dc' : '#333333',
						},
						grid: { vertLines: { visible: false }, horzLines: { visible: false } },
						crosshair: { mode: LightweightCharts.CrosshairMode.Normal, horzLine: { labelBackgroundColor: 'blue' } },
						rightPriceScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc' },
						timeScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc', timeVisible: true, secondsVisible: false },
						localization: {
							timeFormatter: ts => new Date(ts * 1000).toLocaleString('de-DE', {
								timeZone: 'UTC',
								month: 'short', day: 'numeric',
								hour: '2-digit', minute: '2-digit',
							}),
						},
					});

					window.addEventListener('resize', () => {
						chart.resize(window.innerWidth, window.innerHeight);
						updateWindowVLine();
					});
					chart.timeScale().subscribeVisibleLogicalRangeChange(() => updateWindowVLine());
					// #tf-bar wraps onto extra rows on a narrow viewport (see its
					// own CSS comment) — #exchange-label/#ruler-info (stacked
					// underneath it) track its actual measured bottom edge via
					// this custom property instead of a hardcoded offset, so a
					// taller (wrapped) toolbar can never overlap them.
					function repositionBelowToolbar() {
						const bar = document.getElementById('tf-bar');
						if (!bar) return;
						const bottom = Math.ceil(bar.getBoundingClientRect().bottom);
						document.documentElement.style.setProperty('--tf-bar-bottom', bottom + 'px');
					}
					window.addEventListener('resize', repositionBelowToolbar);
					repositionBelowToolbar();

					const series = chart.addCandlestickSeries({
						upColor: '#26a69a', downColor: '#ef5350',
						borderVisible: false, wickUpColor: '#26a69a', wickDownColor: '#ef5350',
					});

					// Invisible helper series solely to extend the shared time
					// axis past the last real candle, same mechanism the Delta
					// Chart's own futureAxisSeries uses (dankbit_templates.xml)
					// — candlestick setData() silently drops OHLC-less
					// "whitespace" points, so a real, fully-valued (if
					// invisible) line series is used instead; all series on a
					// chart share one time scale, so its future points extend
					// the same axis the candlesticks and the 4 gamma price
					// lines are drawn on, leaving room to see those lines
					// extend forward instead of ending flush at the last bar.
					const futureAxisSeries = chart.addLineSeries({
						color: 'rgba(0,0,0,0)', lineWidth: 1,
						lastValueVisible: false, priceLineVisible: false, crosshairMarkerVisible: false,
					});

					// The 4 gamma "lines" are horizontal reference lines at the
					// CURRENT (latest) value only — same createPriceLine()
					// pattern /gt/<asset> uses for its own gamma_band lines —
					// not a connected historical time series. Redrawn fresh
					// on every poll (REFRESH, from dankbit.refresh_interval),
					// each replacing its own previous line rather than
					// accumulating one per hour.
					let bcgPriceLine = null, bpgPriceLine = null, scgPriceLine = null, spgPriceLine = null;
					// Dominant Leg line — drawn at the price of whichever of
					// the 4 legs (present, i.e. price != 0) has the largest
					// |gamma value| over the selected Expiry/Window, the same
					// "dominant leg" rule the since-removed AVG line's label
					// used. Its own color (chartColors.dominant), independent
					// of the 4 leg lines and of the "Gamma Legs" checkbox.
					let dominantLegPriceLine = null;
					// Delta = 0 lines (green, dotted) — one per price where the
					// COMBINED portfolio delta of the same Expiry/Window trades
					// the gamma legs use crosses zero (the response's own
					// `latest.delta_zero_prices`, see four_leg_gamma_json).
					// Can be 0..N lines, so kept as an array. Shown/hidden via
					// the "Delta 0" checkbox (checked by default).
					let deltaZeroPriceLines = [];
					// Gamma flip lines (violet, dotted) — one per price where
					// the COMBINED taker-signed portfolio gamma of the same
					// Expiry/Window trades crosses zero (the response's own
					// `latest.gamma_flips`, see four_leg_gamma_json).
					// 0..N lines. Shown/hidden via the "Gamma Flip" checkbox
					// (checked by default).
					let gammaFlipPriceLines = [];
					// Max Pain line (teal) — see refreshFourLegGamma() below,
					// where it's drawn from the same /api/four-leg-gamma
					// response's own top-level `max_pain_price`/
					// `max_pain_total_oi` fields (independent of `hours`/the
					// trades Window and of whether any trades exist in it —
					// see four_leg_gamma_json's own docstring in main.py, Max
					// Pain is a function of currently outstanding open
					// interest, not recent trade flow). Shown/hidden via its
					// own "Max Pain" checkbox (checked by default).
					let maxPainPriceLine = null;
					function clearGammaFlipLines() {
						gammaFlipPriceLines.forEach(l => series.removePriceLine(l));
						gammaFlipPriceLines = [];
					}
					function clearDeltaZeroLines() {
						deltaZeroPriceLines.forEach(l => series.removePriceLine(l));
						deltaZeroPriceLines = [];
						showDeltaSignBox(null);
					}
					// When the combined delta never crosses zero there's no Δ0
					// line to draw — instead the small #delta-sign-box states
					// which side of zero it stays on (the response's own
					// `latest.delta_zero_sign`: "positive"/"negative"/"zero",
					// null whenever a crossing exists). null hides the box.
					function showDeltaSignBox(sign) {
						const box = document.getElementById('delta-sign-box');
						if (!sign) { box.style.display = 'none'; return; }
						const text = { positive: 'Δ > 0 everywhere (no Δ0)', negative: 'Δ < 0 everywhere (no Δ0)', zero: 'Δ = 0 everywhere' };
						const color = { positive: '#2e7d32', negative: '#c62828', zero: '#555' };
						box.textContent = text[sign] || ('Δ ' + sign);
						box.style.color = color[sign] || '#555';
						box.style.display = 'block';
					}

					function setStatus(text) { document.getElementById('status').textContent = text; }

					function lastTradeSuffix() {
						const label = formatLastTradeTs(lastTradeTs);
						return label ? '  ·  Last trade: ' + label : '';
					}

					// Same "N trades" convention the Delta Chart's own footer
					// uses (dankbit_templates.xml) — placed after the "Last
					// trade:" timestamp since it's the count feeding the
					// same Window that timestamp's own staleness matters for.
					function tradeCountSuffix() {
						return tradeCount !== null ? '  ·  ' + tradeCount + ' trades' : '';
					}

					// WINDOW_HOURS is the string 'all' when the "All" option is
					// selected (no trailing-hours trade filter at all — see
					// four_leg_gamma_json), the string 'midnight' when the
					// "00:00 UTC" option is selected (trades since the most
					// recent UTC midnight instead of a trailing-hours count),
					// the string 'auto' when the "Auto (Time to Expiry)"
					// option is selected (server picks the window, see
					// autoResolvedHours above), or a number otherwise. A value
					// that's a whole multiple of 24 displays in days rather
					// than hours (matters mainly for "Auto", which can resolve
					// to a multi-day span for a far-dated expiry — the dropdown
					// itself now only offers 1h..8h/24h/All); everything else
					// stays hour-labeled — hoursLabel() applies that same
					// day/hour split to autoResolvedHours too, so "Auto" reads
					// identically to picking that same resolved value by hand.
					function hoursLabel(hours) {
						if (hours >= 24 && hours % 24 === 0) return (hours / 24) + 'd';
						return hours + 'h';
					}
					function windowLabel() {
						if (WINDOW_HOURS === 'all') return 'all trades';
						if (WINDOW_HOURS === 'midnight') return 'since 00:00 UTC';
						if (WINDOW_HOURS === 'auto') {
							return autoResolvedHours !== null
								? 'Auto → ' + hoursLabel(autoResolvedHours) + ' trailing window'
								: 'Auto trailing window';
						}
						return hoursLabel(WINDOW_HOURS) + ' trailing window';
					}

					function statusText() {
						return ASSET + ' · 4L (' + windowLabel() + ', live)'
							+ lastTradeSuffix() + tradeCountSuffix();
					}

					async function refreshLastTrade() {
						const data = await (await fetch(LAST_TRADE_URL)).json();
						lastTradeTs = data.last_trade_ts || null;
						setStatus(statusText());
					}

					function showSpinner() { document.getElementById('spinner').style.display = 'block'; }
					function hideSpinner() { document.getElementById('spinner').style.display = 'none'; }

					function toCandle(k) {
						return { time: Math.floor(k.t / 1000) + tzOffset, open: parseFloat(k.o), high: parseFloat(k.h), low: parseFloat(k.l), close: parseFloat(k.c) };
					}

					let realCandles = [];

					// Same per-timeframe visible-window convention the
					// Delta/Gamma/Strike Gamma charts' own TF_WINDOW uses
					// (15m entry matches /gt/<asset>'s own TF_WINDOW).
					const TF_WINDOW = { '15m': 5, '1h': 30, '4h': 15, '1d': 365 };
					// Seconds per bar at each Timeframe — feeds the future-axis
					// tick spacing below (INTERVAL_SECONDS isn't needed
					// anywhere else on this page, unlike the Delta Chart's own
					// copy, which also uses it for its logical-range math).
					const INTERVAL_SECONDS = { '15m': 15 * 60, '1h': 3600, '4h': 4 * 3600, '1d': 86400 };
					// Same future-margin length as the Delta Chart's own
					// FUTURE_MARGIN_DAYS.
					const FUTURE_MARGIN_DAYS = 5;

					function applyVisibleRange() {
						if (!realCandles.length) return;
						const days = TF_WINDOW[INTERVAL] || 15;
						// Ends at the future-axis edge (see futureAxisSeries
						// above), not at the last real candle, so the visible
						// window always includes the future margin rather than
						// leaving it just off-screen to the right.
						const futureEdge = realCandles[realCandles.length - 1].time + FUTURE_MARGIN_DAYS * 86400;
						chart.timeScale().setVisibleRange({ from: futureEdge - days * 86400, to: futureEdge });
					}

					// Rebuilds both the real candle series and the invisible
					// future-axis extension together, so the two never fall
					// out of sync (same pattern the Delta Chart's own
					// rebuildSeriesData() uses).
					function rebuildSeriesData() {
						series.setData(realCandles);

						const intervalSec = INTERVAL_SECONDS[INTERVAL] || 3600;
						const lastClose = realCandles.length ? realCandles[realCandles.length - 1].close : 0;
						const lastTime = realCandles.length
							? realCandles[realCandles.length - 1].time
							: (Math.floor(Date.now() / 1000) + tzOffset);
						const count = Math.round(FUTURE_MARGIN_DAYS * 86400 / intervalSec);
						const futureTicks = [];
						for (let i = 1; i <= count; i++) {
							futureTicks.push({ time: lastTime + i * intervalSec, value: lastClose });
						}
						futureAxisSeries.setData(futureTicks);
						updateWindowVLine();
					}

					// Resolves the current Window selection to a plain hours
					// count for the vertical reference line, or null when no
					// line should be drawn: "All" has no start edge to mark,
					// and "Auto" has none until the server has resolved it
					// (autoResolvedHours). "midnight" (not in this page's own
					// dropdown but still reachable via setWindow) maps to the
					// hours elapsed since the most recent UTC midnight.
					function effectiveWindowHours() {
						if (WINDOW_HOURS === 'all') return null;
						if (WINDOW_HOURS === 'auto') return autoResolvedHours;
						if (WINDOW_HOURS === 'midnight') {
							const nowSec = Math.floor(Date.now() / 1000);
							return (nowSec % 86400) / 3600;
						}
						return WINDOW_HOURS;
					}

					// timeToCoordinate() only resolves a coordinate for a time
					// matching an existing data/whitespace point on the shared
					// time axis — not an arbitrary instant — so the target
					// "now - N hours" is first snapped to the nearest loaded
					// candle at-or-before it (binary search over the
					// already-ascending realCandles).
					function nearestCandleTimeAtOrBefore(t) {
						if (!realCandles.length) return null;
						let lo = 0, hi = realCandles.length - 1, ans = -1;
						while (lo <= hi) {
							const mid = (lo + hi) >> 1;
							if (realCandles[mid].time <= t) { ans = mid; lo = mid + 1; }
							else hi = mid - 1;
						}
						return ans === -1 ? realCandles[0].time : realCandles[ans].time;
					}

					// "Window Line" checkbox (right after "Theme", checked by
					// default) — a plain client-side show/hide flag for the
					// single Window vertical line + label; no effect on the
					// Window dropdown or any fetch.
					let VLINE_SHOWN = true;
					function onToggleVLine() {
						VLINE_SHOWN = document.getElementById('vline-toggle').checked;
						updateWindowVLine();
					}

					// "Gamma Legs" checkbox (right after "Window Line",
					// UNCHECKED by default since 2026-09-23) — plain client-side show/hide flag
					// for the 4 gamma-leg lines (LC/LP/SC/SP). Unchecking removes the 4 lines
					// immediately without a fetch; checking re-fetches via
					// refreshFourLegGamma() since the last-fetched `latest`
					// values aren't cached client-side.
					let SHOW_GAMMA_LEGS = false;
					function onToggleGammaLegs() {
						SHOW_GAMMA_LEGS = document.getElementById('gamma-legs-toggle').checked;
						if (!SHOW_GAMMA_LEGS) {
							if (bcgPriceLine) { series.removePriceLine(bcgPriceLine); bcgPriceLine = null; }
							if (bpgPriceLine) { series.removePriceLine(bpgPriceLine); bpgPriceLine = null; }
							if (scgPriceLine) { series.removePriceLine(scgPriceLine); scgPriceLine = null; }
							if (spgPriceLine) { series.removePriceLine(spgPriceLine); spgPriceLine = null; }
						} else {
							refreshFourLegGamma();
						}
					}

					// "Dominant Leg" checkbox (right after "Gamma Legs",
					// CHECKED by default) — same plain client-side toggle
					// pattern: unchecking clears the line without a fetch,
					// checking re-fetches via refreshFourLegGamma().
					let SHOW_DOMINANT_LEG = true;
					function onToggleDominantLeg() {
						SHOW_DOMINANT_LEG = document.getElementById('dominant-leg-toggle').checked;
						if (!SHOW_DOMINANT_LEG) {
							if (dominantLegPriceLine) { series.removePriceLine(dominantLegPriceLine); dominantLegPriceLine = null; }
						} else {
							refreshFourLegGamma();
						}
					}

					// "Gamma Flip" checkbox (right after "Delta 0", CHECKED by
					// default) — same plain client-side toggle pattern.
					let SHOW_GAMMA_FLIP = true;
					function onToggleGammaFlip() {
						SHOW_GAMMA_FLIP = document.getElementById('gamma-flip-toggle').checked;
						if (!SHOW_GAMMA_FLIP) {
							clearGammaFlipLines();
						} else {
							refreshFourLegGamma();
						}
					}

					// "Max Pain" checkbox (right after "Gamma Flip", CHECKED by
					// default) — plain client-side show/hide flag for the Max
					// Pain line. Unlike every other line on this page, it's
					// drawn from a top-level response field
					// (data.max_pain_price), not from `latest`/the trades
					// Window — see refreshFourLegGamma() below. Unchecking
					// removes the line immediately without a fetch; checking
					// re-fetches via refreshFourLegGamma() since the
					// last-fetched value isn't cached client-side.
					let SHOW_MAX_PAIN = true;
					function onToggleMaxPain() {
						SHOW_MAX_PAIN = document.getElementById('maxpain-toggle').checked;
						if (!SHOW_MAX_PAIN) {
							if (maxPainPriceLine) { series.removePriceLine(maxPainPriceLine); maxPainPriceLine = null; }
						} else {
							refreshFourLegGamma();
						}
					}

					// "Delta 0" checkbox (right after "Dominant Leg", CHECKED by
					// default) — same plain client-side toggle pattern as the
					// others: unchecking clears the lines without a fetch,
					// checking re-fetches via refreshFourLegGamma().
					let SHOW_DELTA_ZERO = true;
					function onToggleDeltaZero() {
						SHOW_DELTA_ZERO = document.getElementById('delta-zero-toggle').checked;
						if (!SHOW_DELTA_ZERO) {
							clearDeltaZeroLines();
						} else {
							refreshFourLegGamma();
						}
					}

					// Positions the single Window reference line (and its label)
					// at the candle `effectiveWindowHours()` hours before now —
					// the start of the currently selected trailing Window.
					// Hidden when the checkbox is off, when Window is "All", or
					// when the target instant falls outside the visible range.
					function updateWindowVLine() {
						const vline = document.getElementById('window-vline');
						const label = document.getElementById('window-vline-label');
						if (!vline) return;
						const hrs = effectiveWindowHours();
						const hideAll = () => {
							vline.style.display = 'none';
							if (label) label.style.display = 'none';
						};
						if (!VLINE_SHOWN || hrs === null || hrs === undefined) { hideAll(); return; }
						const t = Math.floor(Date.now() / 1000) - hrs * 3600 + tzOffset;
						const snapped = nearestCandleTimeAtOrBefore(t);
						const x = snapped === null ? null : chart.timeScale().timeToCoordinate(snapped);
						if (x === null || x === undefined) { hideAll(); return; }
						const rect = chartContainerEl.getBoundingClientRect();
						const left = Math.round(rect.left + x);
						vline.style.left = left + 'px';
						vline.style.display = 'block';
						if (label) {
							const sel = document.getElementById('window-select');
							label.textContent = (WINDOW_HOURS === 'auto' && autoResolvedHours !== null)
								? hoursLabel(autoResolvedHours)
								: (sel && sel.selectedOptions[0] ? sel.selectedOptions[0].textContent : hoursLabel(hrs));
							label.style.left = left + 'px';
							label.style.display = 'block';
						}
					}

					function resetChartView() {
						chart.priceScale('right').applyOptions({ autoScale: true });
						applyVisibleRange();
					}

					const contextMenu = document.getElementById('context-menu');

					function hideContextMenu() {
						contextMenu.style.display = 'none';
					}

					function showContextMenu(x, y) {
						contextMenu.style.display = 'block';
						const maxX = window.innerWidth - contextMenu.offsetWidth - 4;
						const maxY = window.innerHeight - contextMenu.offsetHeight - 4;
						contextMenu.style.left = Math.min(x, maxX) + 'px';
						contextMenu.style.top = Math.min(y, maxY) + 'px';
					}

					function onResetChartViewClick() {
						resetChartView();
						hideContextMenu();
					}

					const chartContainerEl = document.getElementById('chart-container');
					chartContainerEl.addEventListener('contextmenu', e => {
						e.preventDefault();
						showContextMenu(e.clientX, e.clientY);
					});
					document.addEventListener('contextmenu', e => {
						if (!chartContainerEl.contains(e.target)) hideContextMenu();
					});
					document.addEventListener('click', hideContextMenu);
					window.addEventListener('resize', hideContextMenu);
					window.addEventListener('scroll', hideContextMenu, true);

					async function loadCandles() {
						const resp = await (await fetch(klineUrl(INTERVAL, 500))).json();
						const klines = (resp.result || []).slice().reverse();
						realCandles = klines.map(toCandle);
						rebuildSeriesData();
						applyVisibleRange();
						// rebuildSeriesData() already calls updateWindowVLine(),
						// but that runs before applyVisibleRange() establishes
						// the real visible window on first load — recompute here
						// so the line reflects the actual window immediately.
						updateWindowVLine();
					}

					async function updateLatestCandle() {
						const resp = await (await fetch(klineUrl(INTERVAL, 2))).json();
						const klines = resp.result || [];
						if (!klines.length) return;
						const updated = toCandle(klines[0]);
						if (realCandles.length && realCandles[realCandles.length - 1].time === updated.time) {
							realCandles[realCandles.length - 1] = updated;
						} else {
							realCandles.push(updated);
						}
						rebuildSeriesData();
					}

					async function setTf(iv) {
						INTERVAL = iv;
						await loadCandles();
					}

					async function setExpiry(instr) {
						SELECTED_INSTRUMENT = instr;
						await refreshFourLegGamma();
					}

					// Populates the "Expiry" dropdown from every currently
					// active (non-expired) instrument for ASSET — see
					// /api/expiries/<asset> and the SELECTED_INSTRUMENT
					// comment above. Selects the nearest (first, soonest)
					// entry by default. Called once from init(), before the
					// first refreshFourLegGamma() call, so
					// SELECTED_INSTRUMENT is resolved
					// before it's needed.
					async function loadExpiries() {
						const select = document.getElementById('expiry-select');
						if (!select) return;
						const data = await (await fetch('/api/expiries/' + ASSET)).json();
						const expiries = data.expiries || [];
						select.innerHTML = '';
						expiries.forEach(instr => {
							const opt = document.createElement('option');
							opt.value = instr;
							opt.textContent = instr;
							select.appendChild(opt);
						});
						SELECTED_INSTRUMENT = expiries.length ? expiries[0] : null;
						if (SELECTED_INSTRUMENT) select.value = SELECTED_INSTRUMENT;
						// The Expiry select's own width can change once real
						// instrument strings replace its initial empty state,
						// which can shift how #tf-bar wraps.
						repositionBelowToolbar();
					}

					async function setWindow(hours) {
						WINDOW_HOURS = (hours === 'all' || hours === 'midnight' || hours === 'auto') ? hours : parseInt(hours, 10);
						autoResolvedHours = null;
						updateWindowVLine();
						await refreshFourLegGamma();
						setStatus(statusText());
					}

					// Rounds and abbreviates large raw dollar-gamma values
					// (hundreds of millions to billions is typical here) —
					// thousands as K, millions as M, sign preserved (long
					// legs' gamma is positive, short legs' is negative, per
					// this addon's own convention — see per_leg_greeks).
					function formatAbbreviated(value) {
						const sign = value < 0 ? '-' : '';
						const abs = Math.abs(value);
						if (abs >= 1e6) return sign + Math.round(abs / 1e6).toLocaleString('en-US') + 'M';
						if (abs >= 1e3) return sign + Math.round(abs / 1e3).toLocaleString('en-US') + 'K';
						return sign + Math.round(abs).toLocaleString('en-US');
					}

					// Only the LATEST persisted row is used — /api/four-leg-gamma
					// still returns the full history (unchanged backend), this
					// page just draws a horizontal line at each leg's own
					// current value instead of the whole time series.

					// Shows #spinner for the duration of the fetch — this
					// endpoint recomputes the 4-leg gamma curve fresh
					// server-side on every call (no persisted history behind
					// this page), so it can take noticeably longer than the
					// plain klines poll. Hidden in a finally so a fetch
					// error still clears it rather than leaving it spinning
					// forever — same pattern the /gt page's own
					// refreshGammaTriple() uses.
					async function refreshFourLegGamma() {
						showSpinner();
						try {
							const data = await (await fetch(fourLegGammaUrl())).json();
							const points = data.points || [];
							const latest = points.length ? points[points.length - 1] : null;

							// Server-resolved window in hours (always present,
							// even with zero points) — only meaningful for
							// display while WINDOW_HOURS === 'auto', see
							// windowLabel()/hoursLabel() above.
							autoResolvedHours = typeof data.window_hours === 'number' ? data.window_hours : null;
							// "Auto" only knows its real trailing-hours span once
							// the server resolves it — reposition the line now.
							updateWindowVLine();

							// 0 (not null) once resolved with no trades at all in
							// the current Window/Expiry — null only ever means
							// "haven't fetched yet", so tradeCountSuffix() can
							// tell "0 trades" apart from "not loaded".
							tradeCount = latest ? latest.trade_count : 0;
							setStatus(statusText());

							if (bcgPriceLine) { series.removePriceLine(bcgPriceLine); bcgPriceLine = null; }
							if (bpgPriceLine) { series.removePriceLine(bpgPriceLine); bpgPriceLine = null; }
							if (scgPriceLine) { series.removePriceLine(scgPriceLine); scgPriceLine = null; }
							if (spgPriceLine) { series.removePriceLine(spgPriceLine); spgPriceLine = null; }
							if (dominantLegPriceLine) { series.removePriceLine(dominantLegPriceLine); dominantLegPriceLine = null; }
							clearDeltaZeroLines();
							clearGammaFlipLines();

							// Max Pain — drawn from data's own top-level
							// max_pain_price/max_pain_total_oi fields, not
							// from `latest`/points, since it's independent
							// of the trades Window (see four_leg_gamma_json's
							// own docstring) and so must be drawn even when
							// the selected Window/Expiry has zero trades in
							// it (`latest` null below). 0.0 means absent —
							// same convention as the 4 gamma legs' own
							// price fields.
							if (maxPainPriceLine) { series.removePriceLine(maxPainPriceLine); maxPainPriceLine = null; }
							if (SHOW_MAX_PAIN && data.max_pain_price) {
								const mpColor = chartColors.maxpain;
								maxPainPriceLine = series.createPriceLine({
									price: data.max_pain_price, color: mpColor, lineWidth: 2,
									lineStyle: LightweightCharts.LineStyle.Dashed,
									axisLabelVisible: true, axisLabelColor: mpColor,
									title: 'MP ' + formatAbbreviated(data.max_pain_total_oi),
								});
							}

							if (!latest) {
								return;
							}

							// Delta = 0 — every price where the combined
							// portfolio delta of this Expiry/Window's trades
							// crosses zero (empty list = never crosses).
							if (SHOW_DELTA_ZERO) {
								const dzColor = chartColors.deltazero;
								(latest.delta_zero_prices || []).forEach(price => {
									deltaZeroPriceLines.push(series.createPriceLine({
										price: price, color: dzColor, lineWidth: 2,
										lineStyle: LightweightCharts.LineStyle.Dotted,
										axisLabelVisible: true, axisLabelColor: dzColor,
										title: 'Δ0',
									}));
								});
								showDeltaSignBox(latest.delta_zero_sign);
							}

							// Gamma flip — every price where the combined
							// portfolio gamma of this Expiry/Window's trades
							// crosses zero (empty list = never crosses).
							// Label says which side is positive/negative gamma,
							// e.g. "γ flip (taker): − below / + above" (each entry's own
							// `below`/`above` sign from the server).
							if (SHOW_GAMMA_FLIP) {
								const gfColor = chartColors.gammaflip;
								const sym = sign => sign === 'positive' ? '+' : '−';
								(latest.gamma_flips || []).forEach(flip => {
									gammaFlipPriceLines.push(series.createPriceLine({
										price: flip.price, color: gfColor, lineWidth: 2,
										lineStyle: LightweightCharts.LineStyle.Dotted,
										axisLabelVisible: true, axisLabelColor: gfColor,
										title: 'γ flip (taker): ' + sym(flip.below) + ' below / ' + sym(flip.above) + ' above',
									}));
								});
							}

							// 0.0 means absent (same convention every gamma_band/
							// smart_liq_*_price field in this addon uses) — no
							// line drawn rather than a spurious price-0 line.
							// axisLabelColor matches each line's own color here
							// (unlike most other price lines in this addon, which
							// force a black axis label regardless of line color)
							// so the label is identifiable by color at a glance
							// with 4 lines on one chart. Colors come from
							// chartColors (user-configurable via the "Settings"
							// button/dankbit_4l_chart_colors — see above), not a
							// theme-reactive axisBlack()/fixed constant. Also
							// gated on the "Gamma Legs" checkbox (SHOW_GAMMA_LEGS).
							if (SHOW_GAMMA_LEGS && latest.bcg_price) {
								bcgPriceLine = series.createPriceLine({
									price: latest.bcg_price, color: chartColors.bcg, lineWidth: 2,
									lineStyle: LightweightCharts.LineStyle.Solid,
									axisLabelVisible: true, axisLabelColor: chartColors.bcg,
									title: 'LC ' + formatAbbreviated(latest.bcg_value),
								});
							}
							if (SHOW_GAMMA_LEGS && latest.bpg_price) {
								bpgPriceLine = series.createPriceLine({
									price: latest.bpg_price, color: chartColors.bpg, lineWidth: 2,
									lineStyle: LightweightCharts.LineStyle.Solid,
									axisLabelVisible: true, axisLabelColor: chartColors.bpg,
									title: 'LP ' + formatAbbreviated(latest.bpg_value),
								});
							}
							if (SHOW_GAMMA_LEGS && latest.scg_price) {
								scgPriceLine = series.createPriceLine({
									price: latest.scg_price, color: chartColors.scg, lineWidth: 2,
									lineStyle: LightweightCharts.LineStyle.Solid,
									axisLabelVisible: true, axisLabelColor: chartColors.scg,
									title: 'SC ' + formatAbbreviated(latest.scg_value),
								});
							}
							if (SHOW_GAMMA_LEGS && latest.spg_price) {
								spgPriceLine = series.createPriceLine({
									price: latest.spg_price, color: chartColors.spg, lineWidth: 2,
									lineStyle: LightweightCharts.LineStyle.Solid,
									axisLabelVisible: true, axisLabelColor: chartColors.spg,
									title: 'SP ' + formatAbbreviated(latest.spg_value),
								});
							}
							// Dominant Leg — the present leg (price != 0) with the
							// largest |gamma value| in this Expiry/Window; the line
							// sits at that leg's own gamma price. Label e.g.
							// "DOM LC | 71M". Skipped when no leg is present.
							if (SHOW_DOMINANT_LEG) {
								const legs = [
									{ name: 'LC', price: latest.bcg_price, value: latest.bcg_value },
									{ name: 'LP', price: latest.bpg_price, value: latest.bpg_value },
									{ name: 'SC', price: latest.scg_price, value: latest.scg_value },
									{ name: 'SP', price: latest.spg_price, value: latest.spg_value },
								].filter(leg => leg.price);
								if (legs.length) {
									const dom = legs.reduce((a, b) => Math.abs(b.value) > Math.abs(a.value) ? b : a);
									const domColor = chartColors.dominant;
									dominantLegPriceLine = series.createPriceLine({
										price: dom.price, color: domColor, lineWidth: 2,
										lineStyle: LightweightCharts.LineStyle.Solid,
										axisLabelVisible: true, axisLabelColor: domColor,
										title: 'DOM ' + dom.name + ' | ' + formatAbbreviated(dom.value),
									});
								}
							}
						} finally {
							hideSpinner();
							// The next automatic refresh is REFRESH ms from the
							// moment this one finished — keeps the countdown honest
							// for manual (Refresh Lines / Window / Expiry / …)
							// triggers too, not just the routine poll.
							nextRefreshAt = Date.now() + REFRESH;
							updateRefreshCountdown();
						}
					}

					// Self-rescheduling gamma-line auto-refresh: re-arms only
					// after each refresh actually finishes, so a slow recompute
					// can't stack requests, and a manual "Refresh Lines" click
					// (manualRefreshLines()) restarts the countdown from a full
					// interval rather than leaving a stale timer to fire early.
					let gammaRefreshTimer = null;
					function scheduleGammaRefresh() {
						if (gammaRefreshTimer) clearTimeout(gammaRefreshTimer);
						nextRefreshAt = Date.now() + REFRESH;
						updateRefreshCountdown();
						gammaRefreshTimer = setTimeout(async () => {
							await refreshFourLegGamma();
							scheduleGammaRefresh();
						}, REFRESH);
					}

					// "Refresh Lines" button — recompute the gamma legs, dominant leg, Δ0 and γ flip lines
					// now, then restart the countdown from a clean full interval.
					function manualRefreshLines() {
						refreshFourLegGamma().then(scheduleGammaRefresh);
					}

					// Ticks the #refresh-countdown label down once a second (own
					// setInterval below). "Next Update: MM:SS" while waiting,
					// "refreshing…" during the brief window a fetch is in flight
					// before refreshFourLegGamma()'s finally re-arms nextRefreshAt.
					function updateRefreshCountdown() {
						const el = document.getElementById('refresh-countdown');
						if (!el) return;
						const secs = Math.round((nextRefreshAt - Date.now()) / 1000);
						if (secs <= 0) { el.textContent = 'refreshing…'; return; }
						const mm = String(Math.floor(secs / 60)).padStart(2, '0');
						const ss = String(secs % 60).padStart(2, '0');
						el.textContent = 'Next Update: ' + mm + ':' + ss;
					}

					function applyTheme() {
						document.body.classList.toggle('dark', DARK_MODE);
						chart.applyOptions({
							layout: {
								background: { type: 'solid', color: DARK_MODE ? '#000000' : '#ffffff' },
								textColor: DARK_MODE ? '#d1d4dc' : '#333333',
							},
							rightPriceScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc' },
							timeScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc' },
						});
					}

					function onThemeChange() {
						DARK_MODE = document.getElementById('theme-select').value === 'dark';
						localStorage.setItem(THEME_STORAGE_KEY, DARK_MODE ? 'dark' : 'light');
						applyTheme();
					}

					// "Settings" modal — see COLOR_STORAGE_KEY/DEFAULT_COLORS/
					// chartColors above. Unlike the Delta Chart's own version
					// of these 4 functions (which call applyOptions() on
					// already-created, persistent line series), this page's 4
					// gamma lines are plain createPriceLine()s recreated fresh
					// on every refreshFourLegGamma() call — there's no series
					// object to restyle in place, so Save/Reset just trigger
					// an immediate redraw instead.
					function openSettingsModal() {
						Object.keys(DEFAULT_COLORS).forEach(key => {
							const input = document.getElementById('color-' + key);
							if (input) input.value = chartColors[key];
						});
						document.getElementById('settings-modal').style.display = 'flex';
					}

					function closeSettingsModal() {
						document.getElementById('settings-modal').style.display = 'none';
					}

					function saveChartColors() {
						Object.keys(DEFAULT_COLORS).forEach(key => {
							const input = document.getElementById('color-' + key);
							if (input) chartColors[key] = input.value;
						});
						localStorage.setItem(COLOR_STORAGE_KEY, JSON.stringify(chartColors));
						refreshFourLegGamma();
						closeSettingsModal();
					}

					function resetChartColors() {
						chartColors = Object.assign({}, DEFAULT_COLORS);
						localStorage.removeItem(COLOR_STORAGE_KEY);
						Object.keys(DEFAULT_COLORS).forEach(key => {
							const input = document.getElementById('color-' + key);
							if (input) input.value = chartColors[key];
						});
						refreshFourLegGamma();
					}

					let rulerActive = false;
					let rulerPrice1 = null;
					let rulerLines  = [];

					function toggleRuler() {
						rulerActive = !rulerActive;
						document.getElementById('ruler-btn').classList.toggle('active', rulerActive);
						rulerLines.forEach(l => series.removePriceLine(l));
						rulerLines = [];
						rulerPrice1 = null;
						const info = document.getElementById('ruler-info');
						info.style.display = 'none';
						info.textContent = '';
					}

					chart.subscribeClick(param => {
						if (!rulerActive || !param.point) return;
						const price = series.coordinateToPrice(param.point.y);
						if (rulerPrice1 === null) {
							rulerPrice1 = price;
							rulerLines.push(series.createPriceLine({
								price, color: rulerColor(), lineWidth: 1,
								lineStyle: LightweightCharts.LineStyle.Dashed,
								axisLabelVisible: true, axisLabelColor: DARK_MODE ? '#e8e8e8' : '#000000', title: '①',
							}));
						} else {
							rulerLines.push(series.createPriceLine({
								price, color: rulerColor(), lineWidth: 1,
								lineStyle: LightweightCharts.LineStyle.Dashed,
								axisLabelVisible: true, axisLabelColor: DARK_MODE ? '#e8e8e8' : '#000000', title: '②',
							}));
							const pct = ((price - rulerPrice1) / rulerPrice1 * 100);
							const sign = pct >= 0 ? '+' : '';
							const info = document.getElementById('ruler-info');
							info.style.display = 'block';
							info.textContent = rulerPrice1.toFixed(0) + ' → ' + price.toFixed(0) + '   ' + sign + pct.toFixed(2) + '%';
							rulerPrice1 = null;
						}
					});

					async function init() {
						try {
							await loadCandles();
							await loadExpiries();
							await refreshFourLegGamma();
							await refreshLastTrade();
							setStatus(statusText());
						}
						catch (e) { setStatus('Error: ' + e.message); }
						// Arm the self-scheduling gamma-line refresh only once the
						// initial load has settled, so the first countdown starts
						// from a full clean interval.
						finally { scheduleGammaRefresh(); }
					}
					init();
					updateRefreshCountdown();
					setInterval(updateLatestCandle, 5000);
					// Keep the Window line advancing with real time — its
					// target instant is "now - Window", which drifts continuously.
					setInterval(updateWindowVLine, 5000);
					setInterval(updateRefreshCountdown, 1000);
					// Every "Expiry" option now isolates to a single
					// instrument (see SELECTED_INSTRUMENT above) — no more
					// cumulative "all expiries at once" mode to skip polling
					// for, so the gamma-line refresh (scheduleGammaRefresh, armed
					// in init()) always runs.
					setInterval(refreshLastTrade, REFRESH);
				//

//
					// ---- Chat panel (POST /api/chat/<asset>, controllers/chat.py) ----
					// Sends the page's selected Expiry/Window as context plus the
					// last 2 Q/A turns for follow-ups. One request at a time —
					// answers take ~30-60 s on the local model, so an elapsed-time
					// counter shows while waiting. Answers are rendered with
					// textContent (never innerHTML).
					const chatHistory = [];
					let chatBusy = false;

					function toggleChat() {
						const panel = document.getElementById('chat-panel');
						panel.classList.toggle('open');
						if (panel.classList.contains('open')) {
							clampChatPanel();
							document.getElementById('chat-input').focus();
						}
					}

					// Draggable by its header. Once moved, the panel is
					// positioned by left/top (instead of the default right/
					// bottom corner), kept fully on screen, and the position is
					// remembered per-browser (dankbit_4l_chat_pos).
					const CHAT_POS_KEY = 'dankbit_4l_chat_pos';
					function placeChatPanel(left, top) {
						const panel = document.getElementById('chat-panel');
						const maxLeft = Math.max(0, window.innerWidth - panel.offsetWidth);
						const maxTop = Math.max(0, window.innerHeight - panel.offsetHeight);
						panel.style.left = Math.min(Math.max(0, left), maxLeft) + 'px';
						panel.style.top = Math.min(Math.max(0, top), maxTop) + 'px';
						panel.style.right = 'auto';
						panel.style.bottom = 'auto';
					}
					function clampChatPanel() {
						const panel = document.getElementById('chat-panel');
						if (panel.style.left) placeChatPanel(parseFloat(panel.style.left), parseFloat(panel.style.top));
					}
					(function initChatDrag() {
						const panel = document.getElementById('chat-panel');
						const header = document.getElementById('chat-header');
						try {
							const saved = JSON.parse(localStorage.getItem(CHAT_POS_KEY) || 'null');
							if (saved && Number.isFinite(saved.left) && Number.isFinite(saved.top)) {
								panel.style.left = saved.left + 'px';
								panel.style.top = saved.top + 'px';
								panel.style.right = 'auto';
								panel.style.bottom = 'auto';
							}
						} catch (e) { /* storage unavailable — keep default corner */ }
						let drag = null;
						header.addEventListener('pointerdown', (e) => {
							if (e.target.id === 'chat-close' || e.button !== 0) return;
							const rect = panel.getBoundingClientRect();
							drag = { dx: e.clientX - rect.left, dy: e.clientY - rect.top };
							header.setPointerCapture(e.pointerId);
							e.preventDefault();
						});
						header.addEventListener('pointermove', (e) => {
							if (drag) placeChatPanel(e.clientX - drag.dx, e.clientY - drag.dy);
						});
						const endDrag = () => {
							if (!drag) return;
							drag = null;
							try {
								localStorage.setItem(CHAT_POS_KEY, JSON.stringify({
									left: parseFloat(panel.style.left), top: parseFloat(panel.style.top),
								}));
							} catch (e) { /* ignore */ }
						};
						header.addEventListener('pointerup', endDrag);
						header.addEventListener('pointercancel', endDrag);
						window.addEventListener('resize', clampChatPanel);
					})();

					function chatAppend(cls, text) {
						const box = document.getElementById('chat-messages');
						const div = document.createElement('div');
						div.className = 'chat-msg ' + cls;
						div.dir = 'auto';
						div.textContent = text;
						box.appendChild(div);
						box.scrollTop = box.scrollHeight;
						return div;
					}

					function chatSub(parent, cls, text) {
						const d = document.createElement('div');
						d.className = cls;
						d.textContent = text;
						parent.appendChild(d);
						return d;
					}

					async function sendChat() {
						const input = document.getElementById('chat-input');
						const question = input.value.trim();
						if (!question || chatBusy) return;
						chatBusy = true;
						input.value = '';
						document.getElementById('chat-send').disabled = true;
						chatAppend('user', question);
						const status = document.getElementById('chat-status');
						const started = Date.now();
						const tick = setInterval(() => {
							status.textContent = 'Thinking… ' + Math.round((Date.now() - started) / 1000) + 's';
						}, 1000);
						status.textContent = 'Thinking… 0s';
						try {
							const resp = await fetch('/api/chat/' + ASSET, {
								method: 'POST',
								headers: { 'Content-Type': 'application/json' },
								body: JSON.stringify({
									question: question,
									instrument: SELECTED_INSTRUMENT,
									hours: WINDOW_HOURS,
									history: chatHistory.slice(-2),
								}),
							});
							const data = await resp.json().catch(() => ({ error: 'HTTP ' + resp.status }));
							if (!resp.ok || data.error) throw new Error(data.error || ('HTTP ' + resp.status));
							const msg = chatAppend('bot', data.answer);
							if (data.unverified_numbers && data.unverified_numbers.length) {
								chatSub(msg, 'chat-warn', '⚠ Not found in the data: ' + data.unverified_numbers.join(', ') + ' — double-check these.');
							}
							if (data.warning) {
								chatSub(msg, 'chat-warn', '⚠ ' + data.warning);
							}
							if (data.tools && data.tools.length) {
								const det = document.createElement('details');
								const sum = document.createElement('summary');
								sum.textContent = 'Data used: ' + data.tools.map(t => t.name).join(', ');
								const pre = document.createElement('pre');
								pre.textContent = JSON.stringify(data.tools, null, 1);
								det.appendChild(sum);
								det.appendChild(pre);
								msg.appendChild(det);
							}
							chatSub(msg, 'chat-meta', data.model + ' · ' + data.elapsed + 's' + (data.retried ? ' · rewritten' : ''));
							// An answer with flagged numbers never enters the follow-up history —
							// the server treats history numbers as known, so this keeps invented
							// figures from being laundered by "say that in Persian".
							if (!(data.unverified_numbers && data.unverified_numbers.length) && !data.warning) {
								chatHistory.push({ question: question, answer: data.answer });
							}
						} catch (e) {
							chatAppend('error', 'Error: ' + e.message);
						} finally {
							clearInterval(tick);
							status.textContent = '';
							chatBusy = false;
							document.getElementById('chat-send').disabled = false;
							document.getElementById('chat-messages').scrollTop = 1e9;
						}
					}

					document.getElementById('chat-input').addEventListener('keydown', (e) => {
						if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); sendChat(); }
					});
				//
